import re

linkedin_re = re.compile(r'(https?://(?:www\.)?linkedin\.com/[^\s<>"]+)')

def parse_first_last(sender_name):
    if not sender_name:
        return (None, None)
    parts = [p for p in sender_name.strip().split(' ') if p]
    if not parts:
        return (None, None)
    first = parts[0]
    last = parts[-1]
    return first, last

